"""Create the original constant-field Glow fixture; no engine or Adobe invoked.

Keeps only the TIFF and its acquisition manifest in one private directory.
"""
import hashlib
import json
from pathlib import Path
import shutil
import tempfile
import zlib

import numpy as np
import tifffile

ROOT = next(candidate for candidate in Path(__file__).resolve().parents if (candidate / 'package.json').is_file())
ICC_SOURCE = ROOT / 'artifacts/stage-0/acr-reference/glow-tiff-187/input.tif'
ICC_SHA = '2b3aa1645779a9e634744faf9b01e9102b0c9b88fd6deced7934df86b949af7e'
TIFF_SHA = 'fa78bd78ddf224bc7f16751d0e193f0b2c818809d58d8567586ff4c6724a6180'
VALUE = 166 * 257


def sha(data):
    return hashlib.sha256(data).hexdigest()


def main():
    assert tifffile.__version__ == '2026.10.15'
    original_sha = sha(ICC_SOURCE.read_bytes())
    with tifffile.TiffFile(ICC_SOURCE) as f:
        icc = bytes(f.pages[0].tags[34675].value)
    assert sha(icc) == ICC_SHA
    pixels = np.full((2000, 3000, 3), VALUE, dtype=np.uint16)
    work = Path(tempfile.mkdtemp(prefix='captraw-glow-uniform-input-'))
    source = work / 'uniform-gray166-rgb16-srgb.tif'
    try:
        identities = []
        for path in [source, work / 'repeat.tif']:
            tifffile.imwrite(path, pixels, mode='x', byteorder='<', photometric='rgb',
                             planarconfig='contig', compression='deflate',
                             compressionargs={'level': 9}, predictor=False,
                             rowsperstrip=256, subfiletype=0, metadata=None,
                             software=False, datetime=False, resolution=(300, 300),
                             resolutionunit='INCH', iccprofile=icc,
                             extratags=[(274, 'H', 1, 1, False)], maxworkers=1, align=16)
            with tifffile.TiffFile(path) as f:
                page = f.pages[0]
                assert len(f.pages) == 1 and page.shape == pixels.shape
                decoded = page.asarray(maxworkers=1)
                assert decoded.dtype == np.uint16 and np.all(decoded == VALUE)
                assert bytes(page.tags[34675].value) == icc
                assert int(page.compression) in (8, 32946)
                assert not ({270, 305, 306, 700, 33723, 34377, 34665, 34853} &
                            {tag.code for tag in page.tags.values()})
                identities.append({'sha256': sha(path.read_bytes()), 'bytes': path.stat().st_size,
                                   'pixelSHA256': sha(decoded.astype('<u2').tobytes()),
                                   'compressionTag': int(page.compression)})
        assert identities[0] == identities[1], 'Two independent writes differ'
        assert identities[0]['sha256'] == TIFF_SHA, 'Fixed TIFF container identity changed'
        (work / 'repeat.tif').unlink()
        assert sha(ICC_SOURCE.read_bytes()) == original_sha
        manifest = {
            'fixture': 'original-uniform-gray166-rgb16-v1',
            'origin': 'Original mathematical test image generated by this script; no photographic pixels copied, no RAW or added texture/detail.',
            'input': {'file': source.name, **identities[0], 'width': 3000, 'height': 2000,
                      'channels': 3, 'bitsPerSample': 16, 'channelValue': VALUE,
                      'valueDefinition': '166*257 exactly in every R/G/B sample',
                      'iccSource': str(ICC_SOURCE.relative_to(ROOT)),
                      'iccSHA256': ICC_SHA, 'iccBytes': len(icc),
                      'iccPolicy': 'Existing embedded sRGB profile copied byte-for-byte, no pixel transform',
                      'metadata': 'Structural TIFF tags, orientation1, 300PPI and ICC only'},
            'reproducibility': {'independentWrites': 2, 'containerAndPixelIdentical': True,
                                'tifffile': tifffile.__version__, 'numpy': np.__version__,
                                'zlibRuntime': zlib.ZLIB_RUNTIME_VERSION},
            'acquisition': {'application': 'ACR18.7(2743)', 'inputKind': 'rendered TIFF',
                            'states': [{'name': 'baseline0', 'Glow': 0},
                                       {'name': 'diffusion40', 'Glow': 40, 'GlowStyle': 0,
                                        'GlowRange': 50, 'GlowSpread': 50, 'GlowWarmth': 0}],
                            'sharedSettings': 'Identical neutral editing; no masks, resize or output sharpening; RGB16 output with identical sRGB ICC',
                            'centerROI': {'x': 1250, 'y': 750, 'width': 500, 'height': 500,
                                          'coordinates': 'zero-based pixels, right/bottom exclusive'},
                            'comparison': 'Compare the two output center ROIs directly (per-channel delta min/mean/max and ICC-aware deltaY); do not compare only against input166.',
                            'status': 'pending-real-ACR-two-state-capture',
                            'inference': 'No response or positive response has been assumed.'},
        }
        (work / 'manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n')
        print(json.dumps({'directory': str(work), 'input': str(source), **identities[0],
                          'iccSHA256': ICC_SHA, 'channelValue': VALUE}, ensure_ascii=False))
    except BaseException:
        print('Failure retained:', work)
        raise


if __name__ == '__main__':
    main()
